-c-ink);\n}\n\n.heroine[data-accent='rose'] {\n  --c-accent: var(--c-rose);\n  --c-accent-dim: var(--c-rose-dim);\n}\n\n.heroine[data-accent='lily'] {\n  --c-accent: var(--c-lily);\n  --c-accent-dim: var(--c-lily-dim);\n}\n\n.head {\n  display: flex;\n  align-items: center;\n  gap: 6px;\n}\n\n.emblem {\n  width: 15px;\n  height: 15px;\n  flex: none;\n  fill: none;\n  stroke: var(--c-accent);\n  stroke-width: 1.4;\n  stroke-linejoin: round;\n}\n\n.role {\n  font-size: 0.92rem;\n  font-weight: 700;\n  letter-spacing: 0.06em;\n  color: var(--c-accent);\n}\n\n.given {\n  font-size: 0.72rem;\n  color: var(--c-muted);\n}\n\n.stage {\n  margin-left: auto;\n  padding: 0 6px;\n  border: 1px solid var(--c-accent-dim);\n  font-size: 0.72rem;\n  letter-spacing: 0.1em;\n  color: var(--c-paper-dim);\n}\n\n.fall {\n  margin-top: 9px;\n}\n\n.stats {\n  display: grid;\n  gap: 4px;\n  margin-top: 7px;\n  list-style: none;\n}\n\n.facts {\n  display: grid;\n  grid-template-columns: repeat(2, minmax(0, 1fr));\n  gap: 4px 8px;\n  margin-top: 9px;\n}\n\n.fact {\n  display: flex;\n  align-items: baseline;\n  gap: 6px;\n  min-width: 0;\n}\n\n.fact.wide {\n  grid-column: 1 / -1;\n}\n\n.fact dt {\n  flex: none;\n  font-size: 0.7rem;\n  letter-spacing: 0.06em;\n  color: var(--c-muted);\n}\n\n.fact dd {\n  min-width: 0;\n  font-size: 0.78rem;\n  color: var(--c-paper-dim);\n  overflow-wrap: anywhere;\n}\n\n.fact dd[data-on='true'] {\n  font-weight: 700;\n  color: var(--c-accent);\n}\n\n.outfit {\n  margin-top: 9px;\n  padding-top: 6px;\n  border-top: 1px dashed var(--c-line-soft);\n}\n\n.outfit > summary {\n  display: flex;\n  align-items: center;\n  gap: 6px;\n  list-style: none;\n  cursor: pointer;\n}\n\n.outfit > summary::-webkit-details-marker {\n  display: none;\n}\n\n.outfit > summary::before {\n  content: '';\n  flex: none;\n  width: 0;\n  height: 0;\n  border-left: 4px solid var(--c-muted);\n  border-top: 3px solid transparent;\n  border-bottom: 3px solid transparent;\n  transition: transform 0.2s ease;\n}\n\n.outfit[open] > summary::before {\n  transform: rotate(90deg);\n}\n\n.outfit-caption {\n  flex: none;\n  font-size: 0.7rem;\n  letter-spacing: 0.06em;\n  color: var(--c-muted);\n}\n\n.outfit-brief {\n  flex: 1 1 auto;\n  min-width: 0;\n  overflow: hidden;\n  white-space: nowrap;\n  text-overflow: ellipsis;\n  font-size: 0.74rem;\n  color: var(--c-paper-dim);\n}\n\n.outfit-list {\n  display: grid;\n  gap: 2px;\n  margin-top: 6px;\n  list-style: none;\n}\n\n.outfit-list li {\n  display: flex;\n  align-items: baseline;\n  gap: 7px;\n}\n\n.outfit-list .part {\n  flex: none;\n  width: 30px;\n  font-size: 0.7rem;\n  color: var(--c-muted);\n}\n\n.outfit-list .value {\n  min-width: 0;\n  font-size: 0.74rem;\n  color: var(--c-paper-dim);\n  overflow-wrap: anywhere;\n}\n"],"sourceRoot":""}]);
