import { Schema } from '../../schema';
/**
 * 变量还没到位时面板先按默认值显示, 避免整块空白.
 * 顶层五个字段本身没有 catch, 所以要显式给出空对象, 让内层的 catch 兜住默认值.
 */
export const 空数据 = Schema.parse({ 世界: {}, 妈妈: {}, 姐姐: {}, 德里克: {}, 主角: {} });
const 变量来源 = [
    { type: 'message', message_id: 'latest' },
    { type: 'chat' },
    { type: 'message', message_id: 0 },
];
/**
 * MVU 把 stat_data 写进消息楼层变量; 不同版本也可能只留在聊天变量里.
 * 只读, 不写回, 免得和 MVU 自己的变量更新打架.
 */
function 读取原始数据() {
    for (const option of 变量来源) {
        try {
            const stat_data = _.get(getVariables(option), 'stat_data');
            if (!_.isEmpty(stat_data)) {
                return stat_data;
            }
        }
        catch {
            // 这个来源当前不可用, 试下一个
        }
    }
    try {
        const merged = _.get(getAllVariables(), 'stat_data');
        if (!_.isEmpty(merged)) {
            return merged;
        }
    }
    catch {
        // 合并变量表也不可用时就当作还没初始化
    }
    return {};
}
export function usePanelData() {
    const data = ref(空数据);
    const ready = ref(false);
    const refresh = () => {
        const 原始 = 读取原始数据();
        const 结果 = Schema.safeParse(原始);
        if (!结果.success) {
            return;
        }
        if (!_.isEmpty(原始)) {
            ready.value = true;
        }
        if (_.isEqual(data.value, 结果.data)) {
            return;
        }
        data.value = 结果.data;
    };
    refresh();
    // 事件驱动负责及时刷新, 轮询只做兜底
    const 计时器 = window.setInterval(refresh, 1500);
    const 监听 = [
        tavern_events.MESSAGE_RECEIVED,
        tavern_events.MESSAGE_SENT,
        tavern_events.MESSAGE_UPDATED,
        tavern_events.MESSAGE_SWIPED,
        tavern_events.MESSAGE_DELETED,
        tavern_events.CHAT_CHANGED,
    ].map(事件 => eventOn(事件, refresh));
    onUnmounted(() => {
        window.clearInterval(计时器);
        监听.forEach(句柄 => 句柄.stop());
    });
    return { data, ready, refresh };
}
